import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
h={x['id']:x for x in r['context']['history']}
for n in ['r0001-ordinary_pool','r0001-count_corrected_pool','r0001-ordinary_din','r0001-count_corrected_din']:
 x=h[n]; print(n,'auc',x['validation']['auc'],'logloss',x['validation']['logloss'],'wall',x['wall_seconds'])
for n in ['r0001-count_corrected_pool','r0001-count_corrected_din']:
 a=h[n];b=h[n.replace('count_corrected','ordinary')]
 print(n,'minus ordinary')
 for k,s in a['validation']['slices'].items():
  t=b['validation']['slices'][k]
  print(k,json.dumps({'samples':s['samples'],'positives':s['positives'],'negatives':s['negatives'],'auc_delta':s['auc']-t['auc'],'logloss_delta':s['logloss']-t['logloss']}))
